import type { Metadata } from "next";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import ScrollToTop from "@/components/ScrollToTop";
import ScrollReveal from "@/components/ScrollReveal";
import { site } from "@/data";
// Fonts from site.json (theme.fonts), generated by scripts/fonts.mjs.
import { fontVariables } from "./fonts.generated";
import "./globals.css";

export const metadata: Metadata = {
  title: site.site.title,
  description: site.site.description,
};

// Colours come from site.json (theme.colors) and override the globals.css defaults; invalid values are skipped.
const isHex = (v: string) => /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(v);
const themeCss = `:root{${Object.entries(site.theme.colors)
  .filter(([, v]) => isHex(v))
  .map(([k, v]) => `--color-${k}:${v}`)
  .join(";")}}`;

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html
      lang={site.site.lang}
      data-scroll-behavior="smooth"
      // --text-min is the smallest desktop text size. Root font size: 16px, and from 1024px up it follows the 1686px design (1 design px = 1/1686 of the
      // screen), stopping at 1920px. Tailwind v4 leaves buttons on the default cursor, so everything clickable
      // gets the pointer (disabled buttons show not-allowed). With reduced motion turned on nothing transitions.
      className={`${fontVariables} scroll-smooth antialiased [--text-min:11px] [font-size:16px] xl:[font-size:min(calc(1920px/105.375),calc(100vw/105.375))] [&_:where(a[href],button:not(:disabled),select,summary,[role=button],[role=tab],label:has(input[type=checkbox]),input[type=checkbox],input[type=submit])]:cursor-pointer [&_button:disabled]:cursor-not-allowed selection:bg-orange selection:text-white motion-reduce:scroll-auto motion-reduce:**:transition-none`}
    >
      <head>
        <style dangerouslySetInnerHTML={{ __html: themeCss }} />
      </head>
      <body className="bg-cloud font-body text-navy-deep">
        <ScrollReveal />
        {/*
          The site never grows wider than 1920px (105.375rem once the root font size stops growing),
          so on wide screens or when zoomed out it stays centred instead of stretching.
        */}
        <div className="relative mx-auto flex min-h-screen w-full max-w-[105.375rem] flex-col overflow-x-clip bg-white">
          <Navbar />
          <main className="flex-1">
            <ScrollToTop>{children}</ScrollToTop>
          </main>
          <Footer />
        </div>
      </body>
    </html>
  );
}
